<div class="table-wrap"><table><thead><tr><th scope="col" class="number">#</th><th scope="col">Task</th><th scope="col">Scheduled date</th><th scope="col">Status</th></tr></thead><tbody>@forelse($tasks as $task)<tr><td class="number">{{ str_pad($loop->iteration, 2, '0', STR_PAD_LEFT) }}</td><td class="task-title"><span class="task-marker {{ $task->status }}" aria-hidden="true">{{ $task->status === 'completed' ? '✓' : ($task->status === 'in_progress' ? '◔' : '○') }}</span>{{ $task->title }}</td><td><time datetime="{{ $task->task_date->toDateString() }}">{{ $task->task_date->format('M d, Y') }}</time>@if($task->task_date->isToday())<small class="today-tag">Today</small>@endif</td><td><span class="status {{ $task->status }}"><i aria-hidden="true"></i>{{ $task->statusLabel() }}</span></td></tr>@empty<tr><td colspan="4"><div class="empty"><span>✓</span><h3>A little breathing room</h3><p>No tasks are scheduled {{ request()->routeIs('welcome') ? 'for today' : 'yet' }}.</p><a href="{{ route('tasks') }}">View the full task list →</a></div></td></tr>@endforelse</tbody></table></div>
